from pathlib import Path
import json,csv,math,html,shutil,hashlib,re
O=Path(__file__).resolve().parents[1]
def save(name,rows):
 (O/'data'/f'{name}.json').write_text(json.dumps(rows,indent=2,ensure_ascii=False))
 with (O/'data'/f'{name}.csv').open('w',newline='') as f:
  keys=list(dict.fromkeys(k for row in rows for k in row));w=csv.DictWriter(f,fieldnames=keys);w.writeheader();w.writerows(rows)

